1612: function updateDisassemblyLabels() {
1613:   const stage = $('disassemblyStage');
1614:   const labels = $('disassemblyLabels');
1615:   const leaders = $('disassemblyLeaders');
1616:   const show = disassemblyProgress > .72;
1617:   labels.classList.toggle('show', show);
1618:   leaders.classList.toggle('show', show);
1619:   labels.setAttribute('aria-hidden', show ? 'false' : 'true');
1620:   if (!show) return;
1621:   const width = stage.clientWidth;
1622:   const height = stage.clientHeight;
1623:   leaders.setAttribute('viewBox', `0 0 ${width} ${height}`);
1624:   const narrow = width < 720;
1625:   const minLeft = width * (narrow ? .46 : .38);
1626:   const projected = new THREE.Vector3();
1627:   const anchors = [];
1628:   let previousBottom = -Infinity;
1629:   disassemblyCamera.updateMatrixWorld();
1630:   disassemblyRoot.updateMatrixWorld(true);
1631:   DISASSEMBLY_PARTS.forEach((part, index) => {
1632:     const label = disassemblyLabelEls[index];
1633:     if (!label) return;
1634:     projected.set(0, part.slot, 0).applyMatrix4(disassemblyRoot.matrixWorld).project(disassemblyCamera);
1635:     const sx = (projected.x * .5 + .5) * width;
1636:     const sy = (-projected.y * .5 + .5) * height;
1637:     const labelWidth = label.offsetWidth || 180;
1638:     const labelHeight = label.offsetHeight || 44;
1639:     let top = sy - labelHeight / 2;
1640:     top = Math.max(12, Math.min(height - labelHeight - 12, Math.max(top, previousBottom + 7)));
1641:     previousBottom = top + labelHeight;
1642:     const left = Math.max(minLeft, Math.min(width - labelWidth - 12, sx + (narrow ? 22 : 38)));
1643:     label.style.transform = `translate3d(${left.toFixed(1)}px, ${top.toFixed(1)}px, 0)`;
1644:     anchors.push({ sx: sx + part.edge, sy, left, ly: top + labelHeight / 2 });
1645:   });
1646:   anchors.forEach((anchor, index) => {
1647:     const leader = disassemblyLeaderEls[index];
1648:     if (!leader) return;
1649:     leader.line.setAttribute('x1', anchor.sx.toFixed(1));
1650:     leader.line.setAttribute('y1', anchor.sy.toFixed(1));
1651:     leader.line.setAttribute('x2', anchor.left.toFixed(1));
1652:     leader.line.setAttribute('y2', anchor.ly.toFixed(1));
1653:     leader.dot.setAttribute('cx', anchor.sx.toFixed(1));
1654:     leader.dot.setAttribute('cy', anchor.sy.toFixed(1));
1655:     const active = DISASSEMBLY_PARTS[index].id === disassemblyActivePart;
