1695: function layoutDisassemblyCamera() {
1696:   const width = Math.max(1, disassemblyCanvas.clientWidth);
1697:   const height = Math.max(1, disassemblyCanvas.clientHeight);
1698:   const aspect = width / height;
1699:   disassemblyCamera.aspect = aspect;
1700:   const halfFov = THREE.MathUtils.degToRad(34) / 2;
1701:   const fitHeight = 2.45 + 2.7 * disassemblyProgress;
1702:   const fitWidth = 2.2 + 1.15 * disassemblyProgress;
1703:   const distance = Math.max(fitHeight / Math.tan(halfFov), fitWidth / (Math.tan(halfFov) * aspect)) + 1.15;
1704:   const shift = disassemblyProgress * (aspect < .9 ? .7 : .58);
1705:   disassemblyCamera.position.set(shift, .5, distance);
1706:   disassemblyCamera.lookAt(shift, .38, 0);
1707:   disassemblyCamera.updateProjectionMatrix();
1708:   disassemblyCamera.updateMatrixWorld();
1709:   disassemblyCameraProgress = disassemblyProgress;
1710: }
