import { chromium } from 'playwright-core';
import { fileURLToPath } from 'url';

const dir = '/home/runner/work/PlayGround/PlayGround';
const exe = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';
const browser = await chromium.launch({ executablePath: exe, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push(String(e)));
await page.goto(`file://${dir}/index.html`, { waitUntil: 'load' });
await page.waitForTimeout(3500);

const shot = async name => page.screenshot({ path: `${dir}/screenshots/${name}.jpg`, type: 'jpeg', quality: 72 });

// open activities + disassembly
await page.click('#activitiesButton');
await page.waitForTimeout(600);
await shot('check-activities');
await page.click('#activityDisassemble');
await page.waitForTimeout(1200);
await shot('check-disassembly-assembled');
await page.click('#disassembleToggle');
await page.waitForTimeout(2600);
await page.click('.part-label[data-part="crystal"]');
await page.waitForTimeout(500);
await shot('check-disassembly-crystal');
await page.click('.part-label[data-part="pommel"]');
await page.waitForTimeout(400);
await shot('check-disassembly-pommel');
// reassemble
await page.click('#disassembleToggle');
await page.waitForTimeout(2600);
await shot('check-disassembly-reassembled');
const phase = await page.textContent('#disassemblyStatus');
console.log('STATUS AFTER ASSEMBLE:', phase);

// scrap run
await page.click('#disassemblyClose');
await page.waitForTimeout(500);
await page.click('#activitySlicer');
await page.waitForTimeout(900);
await shot('check-slicer-start');
await page.click('#slicerStartButton');
await page.waitForTimeout(2500);
// swipe around to slice things
for (let i = 0; i < 14; i++) {
  await page.mouse.move(380 + (i % 5) * 120, 350 + (i % 3) * 70);
  await page.mouse.down();
  await page.mouse.move(700 - (i % 4) * 110, 300 + (i % 2) * 150, { steps: 8 });
  await page.mouse.up();
  await page.waitForTimeout(360);
}
await shot('check-slicer-play');
const stats = await page.evaluate(() => ({
  score: document.querySelector('#slicerScore').textContent,
  lives: document.querySelector('#slicerLives').textContent,
  time: document.querySelector('#slicerTimer').textContent,
  objects: (window.slicer && window.slicer.objects) ? window.slicer.objects.map(o => o.type) : 'n/a'
}));
console.log('SLICER:', JSON.stringify(stats));
console.log('ERRORS:', errors.length ? errors.join('\n') : 'none');
await browser.close();

