import { chromium } from 'playwright-core';
const dir = '/home/runner/work/PlayGround/PlayGround';
const exe = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';
const browser = await chromium.launch({ executablePath: exe, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox', '--ignore-certificate-errors'] });
for (const [w, h, tag] of [[1024, 700, '1024'], [820, 640, '820']]) {
  const page = await browser.newPage({ viewport: { width: w, height: h } });
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
  await page.waitForTimeout(3000);
  await page.click('#activitiesButton');
  await page.waitForTimeout(350);
  await page.click('#activityDisassemble');
  await page.waitForTimeout(900);
  await page.click('#disassembleToggle');
  await page.waitForTimeout(2600);
  await page.click('.part-label[data-part="switch"]');
  await page.waitForTimeout(450);
  await page.screenshot({ path: `${dir}/screenshots/check-${tag}.jpg`, type: 'jpeg', quality: 72 });
  const box = await page.evaluate(() => {
    const readout = document.querySelector('#disassemblyReadout').getBoundingClientRect();
    const labels = [...document.querySelectorAll('.part-label')].map(el => ({ id: el.dataset.part, ...el.getBoundingClientRect().toJSON() }));
    const stage = document.querySelector('#disassemblyStage').getBoundingClientRect();
    return { readout: readout.toJSON(), stage: stage.toJSON(), labels };
  });
  const stage = box.stage;
  const overflow = box.labels.filter(l => l.x < stage.x || l.y < stage.y || l.right > stage.right || l.bottom > stage.bottom);
  console.log(tag, 'readout', JSON.stringify(box.readout), 'overflow labels', overflow.map(l => l.id));
  console.log(tag, 'errors', errors.length ? errors : 'none');
  await page.close();
}
await browser.close();

import { chromium } from 'playwright-core';
const dir = '/home/runner/work/PlayGround/PlayGround';
const exe = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';
const browser = await chromium.launch({ executablePath: exe, args: ['--use-gl=swiftshader', '--enable-unsafe-swiftshader', '--no-sandbox', '--ignore-certificate-errors'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 2 });
await page.goto('http://127.0.0.1:8123/index.html', { waitUntil: 'load' });
await page.waitForTimeout(3000);
await page.click('#activitiesButton');
await page.waitForTimeout(350);
await page.click('#activityDisassemble');
await page.waitForTimeout(900);
await page.click('#disassembleToggle');
await page.waitForTimeout(2600);
await page.click('.part-label[data-part="crystal"]');
await page.waitForTimeout(500);
const clip = { x: 340, y: 80, width: 620, height: 320 };
await page.screenshot({ path: `${dir}/screenshots/zoom-leaders.jpg`, type: 'jpeg', quality: 82, clip });
const geo = await page.evaluate(() => [...document.querySelectorAll('#disassemblyLeaders g')].map(g => {
  const line = g.querySelector('line');
  return { x1: line.getAttribute('x1'), y1: line.getAttribute('y1'), x2: line.getAttribute('x2'), y2: line.getAttribute('y2') };
}));
console.log(JSON.stringify(geo, null, 1));
await browser.close();

content.text:
/* Activities: disassembly bay, scrap run, and the future duel ring. */
.activities-overlay,.activity-stage-overlay{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:20px;background:#070a08ea;backdrop-filter:blur(10px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s}
.activities-overlay.open,.activity-stage-overlay.open{opacity:1;visibility:visible}
.activity-stage-overlay{z-index:21;padding:16px;background:#050806f2}
.activities-room{position:relative;width:min(1180px,100%);height:min(760px,calc(100vh - 40px));min-height:560px;display:grid;grid-template-rows:64px auto minmax(0,1fr) 42px;overflow:hidden;border:1px solid #48544a;background:radial-gradient(ellipse at 50% 0,#27332b 0,#141a17 48%,#0d1210 100%);box-shadow:0 30px 120px #000c;color:var(--paper)}
.activities-room:before{content:"";position:absolute;inset:0;pointer-events:none;background-image:linear-gradient(#cbd7c006 1px,transparent 1px),linear-gradient(90deg,#cbd7c006 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(ellipse at 50% 30%,#000,transparent 75%)}
.activities-header{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 30px;border-bottom:1px solid #ffffff10;background:#0d120fb8}
.activities-brand,.stage-brand{display:flex;align-items:center;gap:12px}
.activities-brand>div,.stage-brand>div{display:grid;gap:5px}
.activities-brand .eyebrow,.stage-brand .eyebrow{font-size:7px;color:#8e9a90}
.activities-brand strong,.stage-brand strong{font:700 12px var(--sans);letter-spacing:.16em}
.activities-clock{position:absolute;left:50%;transform:translateX(-50%);font:8px var(--mono);letter-spacing:.12em;color:#7d877f}
.activities-clock b{font-weight:400;color:var(--acid)}
.activities-intro{position:relative;z-index:2;display:flex;align-items:flex-end;justify-content:space-between;gap:30px;padding:27px 34px 22px}
.activities-intro .eyebrow{font-size:8px;color:var(--acid)}
.activities-intro h2{margin:9px 0 0;font-size:clamp(25px,3.2vw,39px);line-height:1;letter-spacing:-.06em;font-weight:600}
.activities-intro h2 em{color:var(--acid);font-style:normal}
.activities-intro p{max-width:330px;margin:0 0 3px;color:#929d95;font-size:10px;line-height:1.8}
.activity-grid{position:relative;z-index:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;min-height:0;padding:0 34px 24px}
.activity-card{position:relative;display:flex;flex-direction:column;align-items:stretch;gap:0;min-width:0;min-height:0;padding:15px 16px 16px;text-align:left;border:1px solid #3a443d;background:linear-gradient(160deg,#202722,#171c19 72%);color:var(--paper);font-family:var(--sans);cursor:pointer;overflow:hidden;transition:border-color .22s,transform .22s,background .22s,box-shadow .22s}
.activity-card:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 28%,#d8f36a10,transparent 62%);opacity:0;transition:opacity .25s}
.activity-card:hover,.activity-card:focus-visible{outline:none;border-color:#93a95a;background:linear-gradient(160deg,#252e27,#181e1b 72%);transform:translateY(-3px);box-shadow:0 18px 40px #0007}
.activity-card:hover:before,.activity-card:focus-visible:before{opacity:1}
.activity-index{position:relative;z-index:2;font:8px var(--mono);letter-spacing:.13em;color:#7f8b81}
.activity-art{position:relative;z-index:2;display:grid;place-items:center;flex:1;min-height:110px;margin:6px -6px 2px}
.activity-art svg{width:min(100%,180px);height:auto;max-height:220px;overflow:visible;filter:drop-shadow(0 10px 20px #0006);transition:transform .3s}
.activity-card:hover .activity-art svg,.activity-card:focus-visible .activity-art svg{animation:activityFloat 2.6s ease-in-out infinite}
@keyframes activityFloat{0%,100%{transform:translateY(0)}50%{transform:translateY(-6px)}}
.activity-card strong{position:relative;z-index:2;font-size:20px;line-height:1.1;letter-spacing:-.04em;font-weight:600;margin:2px 0 8px}
.activity-card small{position:relative;z-index:2;color:#8e9991;font-size:9.5px;line-height:1.7;min-height:48px;padding-right:6px}
.activity-cta{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;margin-top:16px;padding-top:12px;border-top:1px solid #ffffff12;font:8px var(--mono);letter-spacing:.12em;color:var(--acid)}
.activity-cta b{font-size:14px;transition:transform .2s}
.activity-card:hover .activity-cta b{transform:translate(2px,-2px)}
.activity-cta.soon{color:#78817a}
.activity-card.is-locked{cursor:not-allowed;background:linear-gradient(160deg,#191f1b,#131815 72%)}
.activity-card.is-locked:hover{transform:none;border-color:#3a443d;box-shadow:none}
.activity-card.is-locked .activity-art{opacity:.62}
.activity-card.is-locked strong{color:#b2bbb3}
.activity-lock{position:absolute;right:9px;top:9px;display:grid;place-items:center;width:24px;height:24px;border:1px solid #465049;border-radius:50%;color:var(--acid);font:14px var(--mono);background:#121714}
.activities-footer{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-top:1px solid #303633;background:#0d120f;color:#78817a;font:7px var(--mono);letter-spacing:.09em}
.activities-footer-center{position:absolute;left:50%;transform:translateX(-50%);color:#6f7a72}
.activities-footer b{font-size:12px;color:var(--acid);margin-left:6px;vertical-align:-1px}

/* Shared full-screen activity stage */
.disassembly-room,.slicer-room{position:relative;width:min(1320px,100%);height:min(840px,calc(100vh - 32px));min-height:560px;display:grid;grid-template-rows:62px minmax(0,1fr) 74px;overflow:hidden;border:1px solid #48544a;background:#0c1110;box-shadow:0 30px 120px #000d;color:var(--paper)}
.activity-stage-header{position:relative;z-index:6;display:flex;align-items:center;justify-content:space-between;gap:22px;padding:0 56px 0 28px;border-bottom:1px solid #313d34;background:#121815}
.stage-status{display:flex;align-items:center;gap:8px;font:8px var(--mono);letter-spacing:.13em;color:#a5afa7}
.stage-status-light{width:6px;height:6px;border-radius:50%;background:var(--acid);box-shadow:0 0 10px #d8f36a99;animation:activityPulse 1.8s infinite}
.stage-status.is-busy .stage-status-light{background:#f2a471;box-shadow:0 0 10px #f2a47199}
.stage-status.is-open .stage-status-light{background:#6fe8ff;box-shadow:0 0 10px #6fe8ff99}
.activity-stage-footer{position:relative;z-index:6;display:flex;align-items:center;justify-content:space-between;gap:22px;padding:0 28px;border-top:1px solid #313d34;background:#111714}
.stage-copy{display:grid;gap:5px;min-width:0}
.stage-copy .eyebrow{font-size:7px;color:var(--acid)}
.stage-copy p{margin:0;color:#8e9991;font-size:9px;line-height:1.5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.stage-actions{display:flex;align-items:center;gap:18px;flex:none}
.stage-actions .primary-button{font-size:9px;padding:13px 18px}
.stage-actions .primary-button span{font-size:13px;margin-left:10px}

@media(max-width:980px){
  .activities-room{grid-template-rows:58px auto minmax(0,1fr) 38px}
  .activity-grid{gap:8px;padding:0 22px 20px}
  .activities-intro{padding:22px 24px 18px}
  .activity-card{padding:12px}
  .activity-card strong{font-size:17px}
  .activity-card small{font-size:8.5px;min-height:58px}
  .activity-art{min-height:86px}
